/* ---------- a small, safe expression evaluator for the plots (no eval) ---------- */
function compile(src){var s=String(src||'').replace(/\s+/g,'').replace(/π/g,'pi').replace(/²/g,'^2'),p=0;
  function peek(){return s[p]}function eat(c){if(s[p]===c){p++;return true}return false}
  function expr(){var a=term();for(;;){if(eat('+')){var b=term(),x=a;a=function(v){return x(v)+b(v)}}else if(eat('-')){var c=term(),y=a;a=function(v){return y(v)-c(v)}}else return a}}
  function term(){var a=unary();for(;;){if(eat('*')){var b=unary(),x=a;a=function(v){return x(v)*b(v)}}else if(eat('/')){var c=unary(),y=a;a=function(v){return y(v)/c(v)}}
    else if(peek()&&/[a-z0-9(.]/.test(peek())){var d=unary(),z=a;a=function(v){return z(v)*d(v)}}else return a}}
  function unary(){if(eat('-')){var a=unary();return function(v){return-a(v)}}if(eat('+'))return unary();return power()}
  function power(){var a=atom();if(eat('^')){var b=unary();return function(v){return Math.pow(a(v),b(v))}}return a}
  var F={sin:Math.sin,cos:Math.cos,tan:Math.tan,sqrt:Math.sqrt,abs:Math.abs,ln:Math.log,log:Math.log,exp:Math.exp,sign:Math.sign,floor:Math.floor};
  function atom(){if(eat('(')){var a=expr();if(!eat(')'))throw 0;return a}
    var m=s.slice(p).match(/^(\d+\.?\d*|\.\d+)/);if(m){p+=m[0].length;var k=parseFloat(m[0]);return function(){return k}}
    m=s.slice(p).match(/^[a-z]+/);if(m){var w=m[0];p+=w.length;
      if(w==='x'||w==='n'||w==='y'||w==='t')return function(v){return v};if(w==='pi')return function(){return Math.PI};if(w==='e')return function(){return Math.E};
      if(F[w]){if(!eat('('))throw 0;var g=expr();if(!eat(')'))throw 0;var fn=F[w];return function(v){return fn(g(v))}}}
    throw 0}
  try{var f=expr();if(p!==s.length)return null;return f}catch(e){return null}}

