  var ys=pts.filter(function(q){return q[1]!=null}).map(function(q){return q[1]});if(!ys.length)return'';var lo=Math.min.apply(0,ys),hi=Math.max.apply(0,ys);if(hi-lo<1e-9){hi+=1;lo-=1}var pad=(hi-lo)*0.15;lo-=pad;hi+=pad;
