/* ---------- Weak spots in every maths prompt ----------
   Every call to Claude in the app goes through getS(). This wraps the sampler it returns so that every maths
   prompt starts with a short note on the student's known weak spots (from notebook pages and three marked tests).
   Claude then keeps them in mind when it writes questions, hints, explanations and marking.
   Prompts for other subjects, and Guest use, are left unchanged. */
(function(){
var TAG='[Known weak spots]';
var WEAK=['quick-fact one-mark questions (definitions, symbols such as ∈ and ⊂, small cases such as n = 0)',
 'long questions left blank instead of writing the formula and first lines',
 'sign, expansion and copying slips (bracket every negative, one move per line)',
 'stopping before the form asked, e.g. degrees left as a decimal instead of degrees, minutes and seconds, or an equation never written',
 'limits: writing a 0/0 form as 0 instead of rewriting first',
 'inequalities: not turning the sign when multiplying by a negative; modulus over x not split into cases',
 'allied angles: the sign and the sin/cos change, and listing every angle in the range',
 'meaning of terms: sector vs circle, A.P. vs G.P., choosing (ⁿCᵣ) vs arranging (ⁿPᵣ)',
 'set proofs given as Venn diagrams instead of elements or set algebra',
 'binomial term numbering: T(r + 1) = ⁿCᵣ aⁿ⁻ʳ bʳ, and n must be a positive whole number',
 'standard products such as sin θ sin(60° − θ) sin(60° + θ) = ¼ sin 3θ'];
var STRONG='proofs once started, counting by cases, rational inequalities with a sign line, recall of standard formulas';
function note(){
  return TAG+' Background on this student, from notebook pages and marked tests. Use it only where it fits the task below. '+
  'Never list it back to the student, and never let it change the output format the task asks for. '+
  'Weak spots, most costly first: '+WEAK.map(function(w,i){return (i+1)+') '+w}).join('; ')+'. '+
  'When writing questions, include ones that test the matching trap where the topic allows. '+
  'When giving a hint, explanation or feedback, check for these slips first and name the habit that prevents the one you see. '+
  'Already strong: '+STRONG+'.';
}
var M=/\bmaths?\b|mathemat|equation|trigonometr|\bsin\b|\bcos\b|\btan\b|quadratic|binomial|\blimits?\b|inequalit|permutation|combination|calculus|derivative|integra|complex number|sequence|series|logarithm|coordinate|parabola|ellipse|hyperbola|probability|\bsets?\b|relation|function|ⁿC|x²/i;
var OTHER=/\b(economics|economy|political science|politics|sociology|philosophy|psychology|history|literature|poem|novel|grammar)\b/i;
function isMaths(p){
  if(M.test(p)&&!OTHER.test(p))return true;
  return /\bmaths?\b|mathemat/i.test(p)&&!/\b(economics|political science|sociology)\b/i.test(p.slice(0,400));
}
function add(p){
  try{
    if(typeof p!=='string'||p.indexOf(TAG)>=0)return p;
    if(typeof ROLE!=='undefined'&&ROLE==='guest')return p;
    if(!isMaths(p))return p;
    return note()+'\n\n'+p;
  }catch(e){return p}
}
var g0=window.getS;if(typeof g0!=='function'||g0.__wk)return;
var base=null,wrapped=null,FN={json:1,text:1,stream:1,complete:1};
async function g(){
  var s=await g0.apply(this,arguments);if(!s)return s;
  if(s===base&&wrapped)return wrapped;
  base=s;
  wrapped=new Proxy(s,{
    apply:function(t,th,a){a=[].slice.call(a);if(a.length)a[0]=add(a[0]);return Reflect.apply(t,th,a)},
    get:function(t,k){var v=Reflect.get(t,k);
      if(typeof v!=='function')return v;
      if(FN[k])return function(){var a=[].slice.call(arguments);if(a.length)a[0]=add(a[0]);return v.apply(t,a)};
      return v.bind(t)}
  });
  return wrapped;
}
g.__wk=1;window.getS=g;
window.SB_WEAKNOTE=note;
})();

