/*GFX3: Batch 3 pictures: sets, functions, and the idea of the derivative. Adds scenes to GFX only. */
(function(){
'use strict';
var G=window.GFX;if(!G||!G.scenes)return;
var SC=G.scenes,N=G.N;
function lens(cx1,cx2,r){var pts=[],h=Math.sqrt(r*r-Math.pow((cx2-cx1)/2,2)),t=Math.atan2(h,(cx2-cx1)/2),i,a;
  for(i=0;i<=16;i++){a=-t+2*t*i/16;pts.push([cx1+r*Math.cos(a),r*Math.sin(a)])}
  for(i=0;i<=16;i++){a=Math.PI-t+2*t*i/16;pts.push([cx2+r*Math.cos(a),r*Math.sin(a)])}return pts}

/* ---- sets ---- */
SC.venn={g:'Sets and functions',t:'Two sets and their overlap',d:'n(A ∪ B) = n(A) + n(B) − n(A ∩ B): the overlap is counted twice',i:'∪',
  view:{x0:-5,x1:5,y0:-3,y1:3.4,eq:1},h:250,
  params:[{k:'a',l:'In A (total)',min:2,max:12,step:1,v:8},{k:'b',l:'In B (total)',min:2,max:12,step:1,v:6},{k:'c',l:'In both',min:0,max:6,step:1,v:3}],
  fix:function(P){if(P.c>P.a)P.c=P.a;if(P.c>P.b)P.c=P.b},
  mini:'Adding n(A) and n(B) counts the overlap twice, so subtract it once: n(A ∪ B) = n(A) + n(B) − n(A ∩ B).',
  read:function(P){return'n(A ∪ B) = '+P.a+' + '+P.b+' − '+P.c+' = <b>'+(P.a+P.b-P.c)+'</b><br>Only A: '+(P.a-P.c)+' · Only B: '+(P.b-P.c)+' · Both: '+P.c},
  steps:[
   {cap:function(P){return'Set A has '+P.a+' members and set B has '+P.b+'. Where the circles overlap are the members that are in both.'},
    draw:function(D,P){D.circ(-1,0,1.9,'a',{w:2.4});D.circ(1,0,1.9,'b',{w:2.4});D.txt(-2.6,2.3,'A','a',{b:1,s:14});D.txt(2.6,2.3,'B','b',{b:1,s:14})}},
   {cap:function(P){return'The overlap is the intersection A ∩ B: '+P.c+' members are in both sets.'},
    draw:function(D,P){D.poly(lens(-1,1,1.9),'ok',{fill:1,op:0.4,w:1.2});D.txt(0,0,String(P.c),'f',{b:1,s:16});D.txt(-2.4,0,String(P.a-P.c),'a',{b:1,s:14});D.txt(2.4,0,String(P.b-P.c),'b',{b:1,s:14})}},
   {cap:function(P){return'Adding '+P.a+' + '+P.b+' counts the '+P.c+' in the overlap twice. Subtract them once: '+P.a+' + '+P.b+' − '+P.c+' = '+(P.a+P.b-P.c)+' members in A ∪ B.'},
    draw:function(D,P){D.txt(0,-2.6,'n(A ∪ B) = '+(P.a+P.b-P.c),'f',{b:1,s:14})}}]};

/* ---- functions ---- */
var FM=[{n:'f(x) = 2x',m:[[0,0],[1,1],[2,2]],v:'a function, and one-to-one: each input has exactly one output and no two inputs share an output'},
 {n:'one input, two outputs',m:[[0,0],[1,1],[1,2],[2,3]],v:'NOT a function: the input 2 has two arrows'},
 {n:'many-to-one',m:[[0,0],[1,0],[2,1]],v:'a function (not one-to-one): each input has exactly one arrow, even if two inputs share an output'}];
var XS=[1,2,3],YS=[[2,4,6,8],[2,4,6,8],[2,4,6,8]];
SC.funcmap={g:'Sets and functions',t:'Relation or function?',d:'A function gives every input exactly one output',i:'f',
  view:{x0:-4,x1:4,y0:-3.3,y1:3.4,eq:1},h:250,params:[{k:'k',l:'Example',min:0,max:2,step:1,v:0,fmt:function(v){return['one-to-one','two outputs','many-to-one'][v]}}],
  mini:'A relation is a function when every input has exactly one arrow. Domain is the inputs, co-domain the whole target set, range the outputs actually reached.',
  read:function(P){var c=FM[P.k],rg={};c.m.forEach(function(p){rg[p[1]]=1});return'<b>'+c.n+'</b>: '+c.v+'.<br>Domain {1, 2, 3} · Co-domain {2, 4, 6, 8} · Range {'+Object.keys(rg).map(function(i){return YS[0][i]}).join(', ')+'}'},
  steps:[
   {cap:'Two sets: the inputs (domain) on the left and the target set (co-domain) on the right.',
    draw:function(D){[[-2.2,'A'],[2.2,'B']].forEach(function(s){D.box(s[0]-0.9,-2.6,1.8,5.2,'m',{w:1.4});D.txt(s[0],2.9,s[1],'f',{b:1,s:13})});
      XS.forEach(function(x,i){D.dot(-2.2,1.6-i*1.6,'a');D.txt(-2.7,1.6-i*1.6-0.15,String(x),'a',{a:'end',b:1,s:13})});
      YS[0].forEach(function(y,i){D.dot(2.2,2-i*1.3,'b');D.txt(2.7,2-i*1.3-0.15,String(y),'b',{a:'start',b:1,s:13})})}},
   {cap:function(P){return'The arrows for "'+FM[P.k].n+'": each arrow joins an input to an output.'},
    draw:function(D,P){FM[P.k].m.forEach(function(p){D.arrow(-2.1,1.6-p[0]*1.6,2.1,2-p[1]*1.3,'ok',{w:2})})}},
   {cap:function(P){return'Check every input: it is '+FM[P.k].v+'.'},
    draw:function(D,P){var c=FM[P.k],cnt={};c.m.forEach(function(p){cnt[p[0]]=(cnt[p[0]]||0)+1});XS.forEach(function(x,i){if(cnt[i]!==1)D.circ(-2.2,1.6-i*1.6,0.4,'b',{w:2.4})});
      D.txt(0,-3.15,cnt[0]===1&&cnt[1]===1&&cnt[2]===1?'function':'not a function','f',{b:1,s:13})}},
   {cap:'The range is only the outputs actually reached; the co-domain is the whole target set. The range sits inside the co-domain.',
    draw:function(D,P){var rg={};FM[P.k].m.forEach(function(p){rg[p[1]]=1});YS[0].forEach(function(y,i){if(rg[i])D.circ(2.2,2-i*1.3,0.4,'ok',{w:2.4})});D.txt(0,-3.15,'rings: the range','ok',{b:1,s:12})}}]};

SC.vlt={g:'Sets and functions',t:'The vertical line test',d:'A graph is a function if no vertical line meets it twice',i:'|',
  view:{x0:-4,x1:4,y0:-4,y1:4,eq:1},params:[{k:'s',l:'Curve',min:0,max:1,step:1,v:0,fmt:function(v){return['y = x² / 2','x = y² / 2'][v]}},{k:'a',l:'Vertical line at x',min:-3,max:3,step:0.5,v:1}],
  mini:'Slide a vertical line across the graph. If it ever meets the curve twice, one input has two outputs, so it is not a function.',
  read:function(P){var n=P.s===0?1:(P.a>0?2:(P.a===0?1:0));return'The line x = '+P.a+' meets the curve <b>'+n+'</b> time'+(n===1?'':'s')+'.'+(P.s===1?' Some lines meet it twice, so it is not a function.':' Every line meets it once, so it is a function.')},
  steps:[
   {cap:function(P){return'The curve '+(P.s===0?'y = x² ÷ 2':'x = y² ÷ 2')+'.'},
    draw:function(D,P){D.axes(-3.8,3.8,-3.8,3.8,{xl:'x',yl:'y'});var pts=[];for(var t=-2.8;t<=2.8;t+=0.1){var u=t*t/2;pts.push(P.s===0?[t,u]:[u,t])}
      D.poly(pts.filter(function(p){return Math.abs(p[0])<=3.9&&Math.abs(p[1])<=3.9}),'a',{w:2.4})}},
   {cap:function(P){return'Draw a vertical line at x = '+P.a+'. Count the points where it meets the curve.'},
    draw:function(D,P){D.line(P.a,-3.8,P.a,3.8,'b',{w:2,d:1});var y=P.s===0?P.a*P.a/2:Math.sqrt(2*Math.max(P.a,0));
      if(P.s===0){if(Math.abs(y)<=3.9)D.dot(P.a,y,'b')}else if(P.a>=0){D.dot(P.a,y,'b');if(y>0)D.dot(P.a,-y,'b')}}},
   {cap:function(P){return P.s===0?'Every vertical line meets y = x² ÷ 2 once at most, so each input has one output: it is a function.':'A vertical line to the right of 0 meets x = y² ÷ 2 twice: one input, two outputs. It is not a function.'},
    draw:function(D,P){D.txt(-2.4,-3.6,P.s===0?'function':'not a function','f',{b:1,s:13})}}]};

/* ---- derivative idea ---- */
function cl(m,x0,y0,v){var xa=v.x0,xb=v.x1,ya=m*(xa-x0)+y0,yb=m*(xb-x0)+y0;
  if(ya<v.y0){xa=x0+(v.y0-y0)/m;ya=v.y0}if(ya>v.y1){xa=x0+(v.y1-y0)/m;ya=v.y1}
  if(yb<v.y0){xb=x0+(v.y0-y0)/m;yb=v.y0}if(yb>v.y1){xb=x0+(v.y1-y0)/m;yb=v.y1}return[xa,ya,xb,yb]}
SC.secant={g:'Calculus ideas',t:'From secant to tangent',d:'The slope of a curve at a point is the limit of secant slopes as h shrinks to 0',i:'d',
  view:{x0:-1,x1:5,y0:-1,y1:10,eq:0},h:280,params:[{k:'x',l:'Point x',min:0.5,max:2.5,step:0.5,v:1.5},{k:'h',l:'Gap h',min:0.5,max:2,step:0.5,v:1.5}],
  mini:'A secant joins two points on the curve. Slide the second point towards the first (h → 0): the secant turns into the tangent, and its slope tends to the derivative. For y = x² that is 2x.',
  read:function(P){return'Secant slope = ((x+h)² − x²) ÷ h = '+(2*P.x+P.h)+'<br>As h → 0 this becomes <b>2x = '+(2*P.x)+'</b>, the slope of the tangent'},
  steps:[
   {cap:function(P){return'The curve y = x² and a point P at x = '+P.x+', where y = '+(P.x*P.x)+'.'},
    draw:function(D,P){D.axes(-0.8,4.8,-0.8,9.6,{xl:'x',yl:'y'});var pts=[];for(var t=-0.8;t<=3.17;t+=0.1)pts.push([t,t*t]);D.poly(pts,'a',{w:2.4});D.dot(P.x,P.x*P.x,'a');D.txt(P.x-0.3,P.x*P.x+0.7,'P','a',{b:1,s:13})}},
   {cap:function(P){var q=P.x+P.h;return'Take a second point Q a distance h = '+P.h+' to the right, at x = '+q+'. The line PQ is a secant. Its slope = rise ÷ run = ('+(q*q)+' − '+(P.x*P.x)+') ÷ '+P.h+' = '+(2*P.x+P.h)+'.'},
    draw:function(D,P){var q=P.x+P.h,s=cl(2*P.x+P.h,P.x,P.x*P.x,D.v||{x0:-1,x1:5,y0:-1,y1:10});D.line(s[0],s[1],s[2],s[3],'b',{w:2});D.dot(q,q*q,'b');D.txt(q+0.25,q*q-0.7,'Q','b',{b:1,s:13})},keep:false},
   {cap:function(P){return'Now let Q slide towards P, so h = 2, 1, 0.5, 0.1… The secant slopes '+[2,1,0.5,0.1].map(function(h){return N(2*P.x+h)}).join(', ')+' settle towards '+(2*P.x)+'. The limiting line is the tangent.'},
    draw:function(D,P){var V={x0:-1,x1:5,y0:-1,y1:10};[2,1,0.5,0.1].forEach(function(h,i){var s=cl(2*P.x+h,P.x,P.x*P.x,V);D.line(s[0],s[1],s[2],s[3],'m',{w:1.4,d:1});var q=P.x+h;D.dot(q,q*q,'m',{r:3})});
      var t=cl(2*P.x,P.x,P.x*P.x,V);D.line(t[0],t[1],t[2],t[3],'ok',{w:2.8});D.txt(4.8,0.4,'tangent: slope '+N(2*P.x),'ok',{a:'end',b:1,s:12})},keep:false},
   {cap:function(P){return'In symbols: dy/dx = limit of ((x + h)² − x²) ÷ h = limit of (2x + h) = 2x. At x = '+P.x+' the slope is 2 × '+P.x+' = '+(2*P.x)+'. This is the derivative.'},
    draw:function(D,P){var t=cl(2*P.x,P.x,P.x*P.x,{x0:-1,x1:5,y0:-1,y1:10});D.line(t[0],t[1],t[2],t[3],'ok',{w:2.8});D.dot(P.x,P.x*P.x,'ok');D.txt(4.8,0.4,'dy/dx = 2x = '+N(2*P.x),'ok',{a:'end',b:1,s:12})}}]};

['venn','funcmap','vlt','secant'].forEach(function(id){G.order.push(id)});
})();

