/*GFX4: Batch 4 pictures: quadratics, trigonometry, conics, probability, dispersion, 3D geometry, differentiation, Pascal. Adds scenes to GFX only. */
(function(){
'use strict';
var G=window.GFX;if(!G||!G.scenes)return;
var SC=G.scenes,N=G.N,sup=G.sup,R=Math.PI/180,PI=Math.PI;
function plot(D,f,a,b,v,c,o,n){n=n||160;var seg=[],i,x,y;
  for(i=0;i<=n;i++){x=a+(b-a)*i/n;y=f(x);if(isFinite(y)&&y>=v.y0&&y<=v.y1)seg.push([x,y]);else{if(seg.length>1)D.poly(seg,c,o);seg=[]}}
  if(seg.length>1)D.poly(seg,c,o)}
function arcp(D,r,a0,a1,c,o,cx,cy){cx=cx||0;cy=cy||0;var pts=[],n=Math.max(4,Math.ceil(Math.abs(a1-a0)/6)),i,a;for(i=0;i<=n;i++){a=(a0+(a1-a0)*i/n)*R;pts.push([cx+r*Math.cos(a),cy+r*Math.sin(a)])}return D.poly(pts,c,o)}
function sg(v,first){return v===0?'':(v>0?(first?'':' + '):(first?'−':' − '))}
function quad(a,b,c){var s='';s+=(a===1?'':(a===-1?'−':a))+'x²';if(b)s+=sg(b)+(Math.abs(b)===1?'':Math.abs(b))+'x';if(c)s+=sg(c)+Math.abs(c);return s}
var AX={xl:'x',yl:'y'};

/* ---- quadratics ---- */
SC.quadgraph={g:'Quadratics and inequalities',t:'Roots and the discriminant',d:'The roots are where the parabola meets the x-axis; D = b² − 4ac decides how many',i:'∪',
  view:{x0:-6,x1:6,y0:-9,y1:9},h:280,params:[{k:'a',l:'a',min:-2,max:2,step:1,v:1},{k:'b',l:'b',min:-6,max:6,step:1,v:-2},{k:'c',l:'c',min:-6,max:6,step:1,v:-3}],
  fix:function(P){if(P.a===0)P.a=1},
  mini:'D = b² − 4ac. If D > 0 the parabola cuts the x-axis twice, D = 0 once (it touches), D < 0 never: the roots are complex.',
  read:function(P){var D=P.b*P.b-4*P.a*P.c;return'<b>'+quad(P.a,P.b,P.c)+' = 0</b><br>D = '+P.b+'² − 4('+P.a+')('+P.c+') = '+D+(D>0?': two real roots':(D===0?': one repeated root':': no real roots (complex pair)'))},
  steps:[
   {cap:function(P){return'The graph of y = '+quad(P.a,P.b,P.c)+' is a parabola that opens '+(P.a>0?'upwards (a > 0)':'downwards (a < 0)')+'.'},
    draw:function(D,P){D.axes(-5.8,5.8,-8.6,8.6,AX);plot(D,function(x){return P.a*x*x+P.b*x+P.c},-6,6,{y0:-9,y1:9},'a',{w:2.4})}},
   {cap:function(P){var v=-P.b/(2*P.a);return'The vertex (turning point) is at x = −b ÷ 2a = '+G.N(v)+', where y = '+G.N(P.a*v*v+P.b*v+P.c)+'. The line x = '+G.N(v)+' is the axis of symmetry.'},
    draw:function(D,P){var v=-P.b/(2*P.a),y=P.a*v*v+P.b*v+P.c;D.line(v,-8.6,v,8.6,'m',{d:1});if(Math.abs(y)<=8.6)D.dot(v,y,'ok');}},
   {cap:function(P){var d=P.b*P.b-4*P.a*P.c;return'Discriminant D = b² − 4ac = '+d+'. '+(d>0?'D > 0: the curve cuts the x-axis at two points, the two real roots x = ('+(-P.b)+' ± √'+d+') ÷ '+(2*P.a)+'.':(d===0?'D = 0: the curve just touches the x-axis: one repeated root.':'D < 0: the curve never reaches the x-axis, so there are no real roots. The roots are complex: (−b ± i√(4ac − b²)) ÷ 2a.'))},
    draw:function(D,P){var d=P.b*P.b-4*P.a*P.c;if(d>=0){var s=Math.sqrt(d);[(-P.b+s)/(2*P.a),(-P.b-s)/(2*P.a)].forEach(function(r){if(Math.abs(r)<=5.8){D.dot(r,0,'b');D.txt(r,-0.9,G.N(r),'b',{b:1,s:11})}})}else D.txt(0,-8,'no real roots','b',{b:1,s:12})}}]};

SC.quadineq={g:'Quadratics and inequalities',t:'Solving a quadratic inequality',d:'Factorise, mark the roots, then read the sign from the graph',i:'<',
  view:{x0:-6,x1:6,y0:-8,y1:12},h:270,params:[{k:'p',l:'Smaller root',min:-4,max:0,step:1,v:-2},{k:'q',l:'Larger root',min:1,max:4,step:1,v:3},{k:'s',l:'Question',min:0,max:1,step:1,v:0,fmt:function(v){return['< 0','> 0'][v]}}],
  mini:'For (x − p)(x − q) < 0 the answer is between the roots; for > 0 it is outside them. Sketch the graph rather than guess.',
  read:function(P){var f='(x '+(P.p>0?'− ':'+ ')+Math.abs(P.p)+')(x − '+P.q+')';return'<b>'+f+(P.s?' > 0':' < 0')+'</b><br>Solution: '+(P.s?'x < '+P.p+' or x > '+P.q:P.p+' < x < '+P.q)},
  steps:[
   {cap:function(P){return'Factorise and find the roots: x = '+P.p+' and x = '+P.q+'. These split the number line into three parts.'},
    draw:function(D,P){D.axes(-5.8,5.8,-7.5,11.5,AX);plot(D,function(x){return(x-P.p)*(x-P.q)},-6,6,{y0:-8,y1:12},'a',{w:2.4});[P.p,P.q].forEach(function(r){D.dot(r,0,'b');D.txt(r,-1,String(r),'b',{b:1,s:12})})}},
   {cap:'The parabola opens upwards: it is below the x-axis (negative) between the roots and above (positive) outside them.',
    draw:function(D,P){D.line(P.p,0,P.q,0,'b',{w:5});D.line(-5.8,0,P.p,0,'ok',{w:5});D.line(P.q,0,5.8,0,'ok',{w:5});D.txt((P.p+P.q)/2,-2.2,'negative','b',{b:1,s:11});D.txt(-4.5,1.6,'positive','ok',{b:1,s:11});D.txt(5,1.6,'positive','ok',{b:1,s:11})}},
   {cap:function(P){return P.s?'For > 0 take the positive parts: x < '+P.p+' or x > '+P.q+' (outside the roots, joined by "or").':'For < 0 take the negative part: '+P.p+' < x < '+P.q+' (between the roots, one connected interval).'},
    draw:function(D,P){D.txt(-3,10.4,P.s?'x < '+P.p+'  or  x > '+P.q:P.p+' < x < '+P.q,'f',{b:1,s:14})},keep:true}]};

/* ---- trigonometry ---- */
SC.trigplot={g:'Trigonometry',t:'Graphs of sine and cosine',d:'Amplitude A stretches up and down; B squeezes sideways, period 2π ÷ B',i:'~',
  view:{x0:-6.6,x1:6.6,y0:-3.6,y1:3.6},h:240,params:[{k:'f',l:'Function',min:0,max:1,step:1,v:0,fmt:function(v){return['sin','cos'][v]}},{k:'A',l:'Amplitude A',min:1,max:3,step:1,v:2},{k:'B',l:'Frequency B',min:1,max:3,step:1,v:1}],
  mini:'y = A sin(Bx): the height peaks at A, and one full wave takes 2π ÷ B along the x-axis.',
  read:function(P){var n=['sin','cos'][P.f];return'<b>y = '+(P.A===1?'':P.A)+n+(P.B===1?'x':'('+P.B+'x)')+'</b><br>Amplitude '+P.A+' · Period 2π ÷ '+P.B+' = '+G.N(360/P.B)+'° (radians: '+(P.B===1?'2π':'2π/'+P.B)+')'},
  steps:[
   {cap:function(P){return'The basic curve y = '+['sin','cos'][P.f]+' x (dashed): it swings between −1 and 1 and repeats every 2π.'},
    draw:function(D,P){D.axes(-6.4,6.4,-3.4,3.4,{xl:'x',yl:''});var f=P.f?Math.cos:Math.sin;plot(D,f,-6.4,6.4,{y0:-4,y1:4},'m',{w:1.6,d:1});[-2*PI,-PI,PI,2*PI].forEach(function(x){D.txt(x,-3.35,Math.round(x/PI)+'π','m',{s:10})})}},
   {cap:function(P){return'The amplitude A = '+P.A+' stretches the curve: it now swings between −'+P.A+' and '+P.A+'.'},
    draw:function(D,P){var f=P.f?Math.cos:Math.sin;plot(D,function(x){return P.A*f(x)},-6.4,6.4,{y0:-4,y1:4},'a',{w:2.4});D.line(-6.4,P.A,6.4,P.A,'ok',{d:1});D.line(-6.4,-P.A,6.4,-P.A,'ok',{d:1})}},
   {cap:function(P){return'B = '+P.B+' squeezes it sideways: the period is 2π ÷ '+P.B+' = '+G.N(360/P.B)+'°. Bigger B gives more waves; it never changes the height.'},
    draw:function(D,P){var f=P.f?Math.cos:Math.sin;plot(D,function(x){return P.A*f(P.B*x)},-6.4,6.4,{y0:-4,y1:4},'b',{w:2.6},400);var T=2*PI/P.B;D.line(0,-P.A-0.5,T,-P.A-0.5,'b',{w:2});D.txt(T/2,-P.A-1.0,'period '+G.N(T*180/PI)+'°','b',{b:1,s:11})},keep:true}]};

SC.radarc={g:'Trigonometry',t:'Radians and arc length',d:'s = rθ when the angle is in radians; degrees × π÷180',i:'⌒',
  view:{x0:-5,x1:5,y0:-5,y1:5,eq:1},params:[{k:'r',l:'Radius r',min:1,max:4,step:1,v:3},{k:'t',l:'Angle θ (degrees)',min:30,max:330,step:30,v:120,u:'°'}],
  mini:'Degrees × π ÷ 180 gives radians. Then arc length s = rθ, and one radian is the angle whose arc equals the radius.',
  read:function(P){var th=P.t*PI/180;return'θ = '+P.t+'° × π÷180 = '+G.N(th)+' rad ('+(P.t/30)+'π÷6)<br>s = rθ = '+P.r+' × '+G.N(th)+' = <b>'+G.N(P.r*th)+'</b>'},
  steps:[
   {cap:function(P){return'A circle of radius r = '+P.r+' and an angle of '+P.t+'° at the centre. The arc is the part of the circle it cuts off.'},
    draw:function(D,P){D.circ(0,0,P.r,'m',{w:1.4});D.line(0,0,P.r,0,'m');arcp(D,P.r,0,P.t,'a',{w:4});D.line(0,0,P.r*Math.cos(P.t*R),P.r*Math.sin(P.t*R),'a',{w:2})}},
   {cap:function(P){return'Convert the angle to radians: '+P.t+'° × π ÷ 180 = '+G.N(P.t*PI/180)+'. Check with 180° = π.'},
    draw:function(D,P){arcp(D,0.9,0,P.t,'b',{w:2.4});D.txt(0.2,0.1,G.N(P.t*PI/180)+' rad','b',{b:1,s:11,a:'start'})}},
   {cap:function(P){return'Arc length s = rθ = '+P.r+' × '+G.N(P.t*PI/180)+' = '+G.N(P.r*P.t*PI/180)+'. It only works with θ in radians. A sector has area ½ r²θ = '+G.N(0.5*P.r*P.r*P.t*PI/180)+'.'},
    draw:function(D,P){var m=P.t/2*R;D.txt((P.r+0.9)*Math.cos(m),(P.r+0.9)*Math.sin(m),'s = '+G.N(P.r*P.t*PI/180),'ok',{b:1,s:12})}},
   {cap:'One radian is the angle where the arc equals the radius: about 57.3°. The full circle holds 2π of them.',
    draw:function(D,P){arcp(D,P.r,0,180/PI,'f',{w:5});D.txt(P.r*Math.cos(0.5)+0.7,P.r*Math.sin(0.5)-0.6,'arc = r','f',{b:1,s:11})},keep:false}]};

SC.compound={g:'Trigonometry',t:'Compound angles: cos(A − B)',d:'cos(A − B) = cosA cosB + sinA sinB, seen on the unit circle',i:'±',
  view:{x0:-1.7,x1:1.7,y0:-1.4,y1:1.7,eq:1},params:[{k:'A',l:'Angle A',min:20,max:90,step:10,v:70,u:'°'},{k:'B',l:'Angle B',min:10,max:80,step:10,v:30,u:'°'}],
  mini:'Two points on the unit circle have coordinates (cos, sin). Their dot product is cos of the angle between them, which gives cos(A − B) = cosA cosB + sinA sinB. It is not cosA − cosB.',
  read:function(P){var a=Math.cos(P.A*R),b=Math.cos(P.B*R),c=Math.sin(P.A*R),d=Math.sin(P.B*R);return'cosA cosB + sinA sinB = '+G.N(a*b)+' + '+G.N(c*d)+' = <b>'+G.N(a*b+c*d)+'</b><br>cos('+(P.A-P.B)+'°) = '+G.N(Math.cos((P.A-P.B)*R))+' (same) · cosA − cosB = '+G.N(a-b)+' (different)'},
  steps:[
   {cap:function(P){return'On the unit circle, point P at angle A = '+P.A+'° is (cos A, sin A) = ('+G.N(Math.cos(P.A*R))+', '+G.N(Math.sin(P.A*R))+').'},
    draw:function(D,P){D.axes(-1.5,1.5,-1.2,1.5,{xl:'',yl:''});D.circ(0,0,1,'m',{w:1.4});D.line(0,0,Math.cos(P.A*R),Math.sin(P.A*R),'a',{w:2.4});D.dot(Math.cos(P.A*R),Math.sin(P.A*R),'a');D.txt(1.25*Math.cos(P.A*R),1.25*Math.sin(P.A*R),'P','a',{b:1})}},
   {cap:function(P){return'Q at angle B = '+P.B+'° is ('+G.N(Math.cos(P.B*R))+', '+G.N(Math.sin(P.B*R))+'). The angle between OP and OQ is A − B = '+(P.A-P.B)+'°.'},
    draw:function(D,P){D.line(0,0,Math.cos(P.B*R),Math.sin(P.B*R),'b',{w:2.4});D.dot(Math.cos(P.B*R),Math.sin(P.B*R),'b');D.txt(1.25*Math.cos(P.B*R),1.25*Math.sin(P.B*R)-0.1,'Q','b',{b:1});arcp(D,0.45,P.B,P.A,'ok',{w:3})}},
   {cap:function(P){return'Multiply matching coordinates and add (the dot product): cos(A − B) = cosA cosB + sinA sinB. Here that gives '+G.N(Math.cos((P.A-P.B)*R))+'.'},
    draw:function(D,P){D.txt(0,-1.2,'cos(A−B) = cosA cosB + sinA sinB','f',{b:1,s:12})}},
   {cap:function(P){return'Careful: cos(A − B) is not cosA − cosB. Here cosA − cosB = '+G.N(Math.cos(P.A*R)-Math.cos(P.B*R))+', but cos(A − B) = '+G.N(Math.cos((P.A-P.B)*R))+'. A function does not spread over a sum.'},
    draw:function(D,P){D.txt(0,-1.2,'','f')}}]};

/* ---- conics ---- */
SC.parabola={g:'Conic sections',t:'Parabola: focus and directrix',d:'Every point is as far from the focus as from the directrix',i:'∮',
  view:{x0:-4.5,x1:9,y0:-7,y1:7,eq:1},params:[{k:'a',l:'a in y² = 4ax',min:1,max:3,step:1,v:2},{k:'y',l:'Point height y',min:-6,max:6,step:1,v:4}],
  mini:'For y² = 4ax the focus is (a, 0) and the directrix is x = −a. Any point on the curve is the same distance from both.',
  read:function(P){var x=P.y*P.y/(4*P.a),d=Math.hypot(x-P.a,P.y);return'Point ('+G.N(x)+', '+P.y+')<br>Distance to focus = '+G.N(d)+' · distance to directrix = '+G.N(x+P.a)+' <b>(equal)</b><br>Latus rectum length 4a = '+4*P.a},
  steps:[
   {cap:function(P){return'The parabola y² = '+(4*P.a)+'x opens to the right. Its vertex is the origin.'},
    draw:function(D,P){D.axes(-4.2,8.8,-6.8,6.8,AX);plot(D,function(x){return Math.sqrt(4*P.a*x)},0,9,{y0:-7,y1:7},'a',{w:2.4});plot(D,function(x){return-Math.sqrt(4*P.a*x)},0,9,{y0:-7,y1:7},'a',{w:2.4})}},
   {cap:function(P){return'Focus F = (a, 0) = ('+P.a+', 0). Directrix: the vertical line x = −a = '+(-P.a)+'.'},
    draw:function(D,P){D.dot(P.a,0,'b');D.txt(P.a+0.35,-0.6,'F','b',{b:1});D.line(-P.a,-6.8,-P.a,6.8,'b',{d:1,w:2})}},
   {cap:function(P){var x=P.y*P.y/(4*P.a);return'Take P = ('+G.N(x)+', '+P.y+') on the curve. Its distance to the focus is '+G.N(Math.hypot(x-P.a,P.y))+' and its distance to the directrix is '+G.N(x+P.a)+'. They are equal: that is the definition.'},
    draw:function(D,P){var x=P.y*P.y/(4*P.a);D.dot(x,P.y,'ok');D.line(x,P.y,P.a,0,'ok',{w:2});D.line(x,P.y,-P.a,P.y,'ok',{w:2})}},
   {cap:function(P){return'The chord through the focus perpendicular to the axis is the latus rectum, of length 4a = '+(4*P.a)+'.'},
    draw:function(D,P){D.line(P.a,-2*P.a,P.a,2*P.a,'f',{w:2.4});D.txt(P.a+0.3,2*P.a+0.5,'4a = '+(4*P.a),'f',{a:'start',b:1,s:11})},keep:false}]};

SC.ellipse={g:'Conic sections',t:'Ellipse: two foci',d:'The distances to the two foci always add up to 2a',i:'◯',
  view:{x0:-6.4,x1:6.4,y0:-4.6,y1:4.6,eq:1},params:[{k:'a',l:'Semi-axis a',min:2,max:6,step:1,v:5},{k:'b',l:'Semi-axis b',min:1,max:4,step:1,v:3},{k:'t',l:'Point angle',min:0,max:330,step:30,v:60,u:'°'}],
  fix:function(P){if(P.b>=P.a)P.b=P.a-1},
  mini:'x²/a² + y²/b² = 1 with a > b. Foci at (±c, 0) where c² = a² − b². Eccentricity e = c ÷ a is below 1.',
  read:function(P){var c=Math.sqrt(P.a*P.a-P.b*P.b);return'c = √('+P.a*P.a+' − '+P.b*P.b+') = '+G.N(c)+' · e = c÷a = '+G.N(c/P.a)+'<br>PF₁ + PF₂ = 2a = <b>'+2*P.a+'</b>'},
  steps:[
   {cap:function(P){return'The ellipse with semi-axes a = '+P.a+' (along x) and b = '+P.b+' (along y): x²/'+P.a*P.a+' + y²/'+P.b*P.b+' = 1.'},
    draw:function(D,P){D.axes(-6.2,6.2,-4.4,4.4,AX);var pts=[];for(var t=0;t<=360;t+=5)pts.push([P.a*Math.cos(t*R),P.b*Math.sin(t*R)]);D.poly(pts,'a',{w:2.4,close:1})}},
   {cap:function(P){var c=Math.sqrt(P.a*P.a-P.b*P.b);return'The foci are at (±c, 0) with c = √(a² − b²) = √'+(P.a*P.a-P.b*P.b)+' = '+G.N(c)+'. Always the longer axis, a, holds them.'},
    draw:function(D,P){var c=Math.sqrt(P.a*P.a-P.b*P.b);[c,-c].forEach(function(f){D.dot(f,0,'b')});D.txt(c,-0.7,'F₂','b',{b:1,s:11});D.txt(-c,-0.7,'F₁','b',{b:1,s:11})}},
   {cap:function(P){return'For any point P on the curve, PF₁ + PF₂ = 2a = '+2*P.a+'. A loop of string of that length pinned at the foci draws the ellipse.'},
    draw:function(D,P){var c=Math.sqrt(P.a*P.a-P.b*P.b),x=P.a*Math.cos(P.t*R),y=P.b*Math.sin(P.t*R);D.line(-c,0,x,y,'ok',{w:2});D.line(c,0,x,y,'ok',{w:2});D.dot(x,y,'ok');D.txt(x,y+0.6,'P','ok',{b:1})}},
   {cap:function(P){var c=Math.sqrt(P.a*P.a-P.b*P.b);return'Eccentricity e = c ÷ a = '+G.N(c/P.a)+'. For an ellipse e is always less than 1; nearer 0 is rounder, nearer 1 is flatter.'},
    draw:function(D,P){D.txt(0,-4.1,'e = '+G.N(Math.sqrt(P.a*P.a-P.b*P.b)/P.a),'f',{b:1,s:12})}}]};

SC.hyperbola={g:'Conic sections',t:'Hyperbola: difference of distances',d:'The distances to the foci differ by 2a; the asymptotes guide the branches',i:')(',
  view:{x0:-8,x1:8,y0:-6,y1:6,eq:1},params:[{k:'a',l:'a',min:1,max:4,step:1,v:2},{k:'b',l:'b',min:1,max:4,step:1,v:3},{k:'t',l:'Point position',min:-2,max:2,step:0.5,v:1}],
  mini:'x²/a² − y²/b² = 1. Foci at (±c, 0) with c² = a² + b² (a plus, unlike the ellipse). Eccentricity e = c ÷ a is above 1.',
  read:function(P){var c=Math.sqrt(P.a*P.a+P.b*P.b);return'c = √('+P.a*P.a+' + '+P.b*P.b+') = '+G.N(c)+' · e = '+G.N(c/P.a)+'<br>Asymptotes y = ±'+G.N(P.b/P.a)+'x · |PF₁ − PF₂| = 2a = <b>'+2*P.a+'</b>'},
  steps:[
   {cap:function(P){return'x²/'+P.a*P.a+' − y²/'+P.b*P.b+' = 1 has two branches, with vertices at (±a, 0) = (±'+P.a+', 0).'},
    draw:function(D,P){D.axes(-7.8,7.8,-5.8,5.8,AX);var L=[],Rr=[],t;for(t=-2.4;t<=2.4;t+=0.1){Rr.push([P.a*Math.cosh(t),P.b*Math.sinh(t)]);L.push([-P.a*Math.cosh(t),P.b*Math.sinh(t)])}
      [L,Rr].forEach(function(b){D.poly(b.filter(function(p){return Math.abs(p[0])<=8&&Math.abs(p[1])<=6}),'a',{w:2.4})})}},
   {cap:function(P){return'Asymptotes y = ±(b ÷ a)x = ±'+G.N(P.b/P.a)+'x (dashed). The branches get closer and closer to them but never touch.'},
    draw:function(D,P){var m=P.b/P.a;D.line(-8,-8*m,8,8*m,'m',{d:1});D.line(-8,8*m,8,-8*m,'m',{d:1})},keep:true},
   {cap:function(P){var c=Math.sqrt(P.a*P.a+P.b*P.b);return'Foci at (±c, 0) with c = √(a² + b²) = '+G.N(c)+', outside the vertices. For any point P, |PF₁ − PF₂| = 2a = '+2*P.a+'.'},
    draw:function(D,P){var c=Math.sqrt(P.a*P.a+P.b*P.b),x=P.a*Math.cosh(P.t),y=P.b*Math.sinh(P.t);[c,-c].forEach(function(f){if(Math.abs(f)<=8)D.dot(f,0,'b')});if(Math.abs(x)<=8&&Math.abs(y)<=6){D.line(-c,0,x,y,'ok',{w:2});D.line(c,0,x,y,'ok',{w:2});D.dot(x,y,'ok')}}}]};

/* ---- probability ---- */
SC.dice={g:'Probability and data',t:'Two dice: counting favourable outcomes',d:'P(event) = favourable ÷ total, using the sample space of 36',i:'⚅',
  view:{x0:0,x1:7.4,y0:0,y1:7.4,eq:1},params:[{k:'s',l:'Sum wanted',min:2,max:12,step:1,v:7}],
  mini:'List the whole sample space (6 × 6 = 36 equally likely outcomes), count the ones that give the sum, and divide by 36.',
  read:function(P){var n=0;for(var i=1;i<=6;i++)for(var j=1;j<=6;j++)if(i+j===P.s)n++;return'P(sum = '+P.s+') = '+n+' ÷ 36 = <b>'+G.N(n/36)+'</b>'},
  steps:[
   {cap:'Roll two dice. Each square is one outcome (first die across, second die up). There are 6 × 6 = 36, all equally likely.',
    draw:function(D){for(var i=1;i<=6;i++)for(var j=1;j<=6;j++)D.box(i-0.42,j-0.42,0.84,0.84,'m',{w:1.1});for(var k=1;k<=6;k++){D.txt(k,0.1,String(k),'m',{s:10});D.txt(0.15,k-0.15,String(k),'m',{s:10})}}},
   {cap:function(P){var n=0;for(var i=1;i<=6;i++)for(var j=1;j<=6;j++)if(i+j===P.s)n++;return'The outcomes with sum '+P.s+' are shaded: '+n+' of them. Notice (1, 2) and (2, 1) are different outcomes.'},
    draw:function(D,P){for(var i=1;i<=6;i++)for(var j=1;j<=6;j++)if(i+j===P.s)D.box(i-0.42,j-0.42,0.84,0.84,'ok',{fill:1,op:0.5,w:1.6})}},
   {cap:function(P){var n=0;for(var i=1;i<=6;i++)for(var j=1;j<=6;j++)if(i+j===P.s)n++;return'Probability = favourable ÷ total = '+n+' ÷ 36 = '+G.N(n/36)+(n===6?' = 1/6':'')+'. A sum of 7 is the most likely; 2 and 12 the least.'},
    draw:function(D,P){D.txt(3.5,7.05,'','f')}}]};

function tn(v){return(v/10).toFixed(1)}
SC.probrule={g:'Probability and data',t:'Addition rule and complement',d:'P(A ∪ B) = P(A) + P(B) − P(A ∩ B)',i:'P',
  view:{x0:-5,x1:5,y0:-3,y1:3.4,eq:1},h:250,params:[{k:'a',l:'P(A)',min:2,max:9,step:1,v:6,fmt:tn},{k:'b',l:'P(B)',min:2,max:9,step:1,v:5,fmt:tn},{k:'c',l:'P(A and B)',min:0,max:5,step:1,v:2,fmt:tn}],
  fix:function(P){var m=Math.min(P.a,P.b);if(P.c>m)P.c=m;if(P.a+P.b-P.c>10)P.c=P.a+P.b-10},
  mini:'Adding P(A) and P(B) counts the overlap twice, so subtract it once. The chance A does not happen is 1 − P(A).',
  read:function(P){var a=P.a/10,b=P.b/10,c=P.c/10;return'P(A or B) = '+a+' + '+b+' − '+c+' = <b>'+(Math.round((a+b-c)*10)/10)+'</b><br>P(A′) = '+(Math.round((1-a)*10)/10)+' · independent? P(A)P(B) = '+(Math.round(a*b*100)/100)+(Math.abs(a*b-c)<1e-9?' = P(A and B): yes':' ≠ P(A and B): no')},
  steps:[
   {cap:function(P){return'Event A has probability '+tn(P.a)+' and event B has '+tn(P.b)+'. The overlap, both happening, has probability '+tn(P.c)+'.'},
    draw:function(D,P){D.circ(-1,0,1.9,'a',{w:2.4});D.circ(1,0,1.9,'b',{w:2.4});D.txt(-2.6,2.3,'A','a',{b:1,s:14});D.txt(2.6,2.3,'B','b',{b:1,s:14});D.txt(0,0,tn(P.c),'f',{b:1,s:14});D.txt(-2.4,0,tn(P.a-P.c),'a',{b:1,s:13});D.txt(2.4,0,tn(P.b-P.c),'b',{b:1,s:13})}},
   {cap:function(P){return'P(A ∪ B) = P(A) + P(B) − P(A ∩ B) = '+tn(P.a)+' + '+tn(P.b)+' − '+tn(P.c)+' = '+(Math.round((P.a+P.b-P.c))/10)+'. The overlap would be counted twice otherwise.'},
    draw:function(D,P){D.txt(0,-2.6,'P(A or B) = '+(P.a+P.b-P.c)/10,'f',{b:1,s:13})},keep:false},
   {cap:function(P){return'The complement: P(A′) = 1 − P(A) = 1 − '+tn(P.a)+' = '+tn(10-P.a)+'. "At least one" questions are easiest as 1 minus "none".'},
    draw:function(D,P){D.txt(0,-2.6,'P(A′) = '+(10-P.a)/10,'b',{b:1,s:13})},keep:false}]};

/* ---- statistics ---- */
SC.disp={g:'Probability and data',t:'Spread: range, variance, standard deviation',d:'How far the values lie from the mean',i:'σ',
  view:{x0:-1,x1:13,y0:-2.2,y1:3.2},h:230,params:[{k:'s',l:'Spread',min:1,max:4,step:1,v:2,fmt:function(v){return v+(v<2?' (tight)':(v>3?' (wide)':''))}}],
  mini:'Mean = sum ÷ n. Variance = the average squared distance from the mean, and standard deviation is its square root. Wider spread means larger σ.',
  read:function(P){var d=ds(P),m=6,v=0;d.forEach(function(x){v+=(x-m)*(x-m)});v/=d.length;return'Mean = '+m+' · range = '+(d[4]-d[0])+'<br>Variance = '+G.N(v)+' · σ = √'+G.N(v)+' = <b>'+G.N(Math.sqrt(v))+'</b>'},
  steps:[
   {cap:function(P){return'Five values on a number line: '+ds(P).map(G.N).join(', ')+'. Their mean is 6.'},
    draw:function(D,P){D.line(-0.5,0,12.5,0,'m');ds(P).forEach(function(x){D.dot(x,0,'a');D.txt(x,-0.7,G.N(x),'a',{s:11,b:1})});D.dot(6,0,'ok',{open:1,r:8});D.txt(6,2.6,'mean 6','ok',{b:1,s:12})}},
   {cap:function(P){var d=ds(P);return'Range = largest − smallest = '+G.N(d[4])+' − '+G.N(d[0])+' = '+G.N(d[4]-d[0])+'. It uses only two values, so one extreme point changes it a lot.'},
    draw:function(D,P){var d=ds(P);D.line(d[0],1.9,d[4],1.9,'b',{w:2.4});D.txt(6,2.3,'range '+G.N(d[4]-d[0]),'b',{b:1,s:11})},keep:false},
   {cap:function(P){return'Each value is a distance from the mean (a deviation). They add to 0, so square them first: the squares are '+ds(P).map(function(x){return G.N((x-6)*(x-6))}).join(', ')+'.'},
    draw:function(D,P){ds(P).forEach(function(x,i){if(x!==6)D.arrow(6,0.5+i*0.25,x,0.5+i*0.25,'b',{w:1.8})})}},
   {cap:function(P){var d=ds(P),v=0;d.forEach(function(x){v+=(x-6)*(x-6)});v/=5;return'Variance = the average of the squares = '+G.N(v)+'. Standard deviation σ = √'+G.N(v)+' = '+G.N(Math.sqrt(v))+', back in the original units.'},
    draw:function(D,P){var d=ds(P),v=0;d.forEach(function(x){v+=(x-6)*(x-6)});var sd=Math.sqrt(v/5);D.line(6-sd,-1.5,6+sd,-1.5,'ok',{w:4});D.txt(6,-2,'mean ± σ','ok',{b:1,s:11})},keep:false}]};
function ds(P){return[-2,-1,0,1,2].map(function(k){return 6+k*P.s*0.75})}

/* ---- 3D geometry ---- */
function pr(x,y,z){return[y-0.45*x,z-0.3*x]}
SC.coord3d={g:'3D geometry',t:'A point in three dimensions',d:'(x, y, z) and the distance from the origin, √(x² + y² + z²)',i:'⧈',
  view:{x0:-3.5,x1:6,y0:-3,y1:6,eq:1},h:300,params:[{k:'x',l:'x',min:-3,max:3,step:1,v:2},{k:'y',l:'y',min:-3,max:4,step:1,v:3},{k:'z',l:'z',min:-3,max:4,step:1,v:3}],
  mini:'Three axes at right angles. A point is reached by moving x along the x-axis, y along the y-axis and z up. Its distance from the origin is √(x² + y² + z²).',
  read:function(P){var d=P.x*P.x+P.y*P.y+P.z*P.z;return'OP = √('+P.x*P.x+' + '+P.y*P.y+' + '+P.z*P.z+') = √'+d+' = <b>'+G.N(Math.sqrt(d))+'</b><br>Distance from the xy-plane = |z| = '+Math.abs(P.z)},
  steps:[
   {cap:'Three axes at right angles: x (drawn coming towards you), y (to the right) and z (up). Any two of them make a coordinate plane.',
    draw:function(D){[['x',4,0,0],['y',0,4.5,0],['z',0,0,4.5]].forEach(function(a){var e=pr(a[1]*1,a[2],a[3]);if(a[0]==='x')e=pr(3.4,0,0);D.arrow(0,0,e[0],e[1],'m',{w:1.8});D.txt(e[0]+0.25,e[1]+0.2,a[0],'f',{b:1,s:13})})}},
   {cap:function(P){return'The point P = ('+P.x+', '+P.y+', '+P.z+'): go '+P.x+' along x, '+P.y+' along y, then '+P.z+' along z. The dashed box shows the path.'},
    draw:function(D,P){var V=[[0,0,0],[P.x,0,0],[P.x,P.y,0],[0,P.y,0],[0,0,P.z],[P.x,0,P.z],[P.x,P.y,P.z],[0,P.y,P.z]].map(function(v){return pr(v[0],v[1],v[2])});
      [[0,1],[1,2],[2,3],[3,0],[4,5],[5,6],[6,7],[7,4],[0,4],[1,5],[2,6],[3,7]].forEach(function(e){D.line(V[e[0]][0],V[e[0]][1],V[e[1]][0],V[e[1]][1],'a',{d:1,w:1.3})});D.dot(V[6][0],V[6][1],'a');D.txt(V[6][0]+0.35,V[6][1]+0.35,'P','a',{b:1,s:13})}},
   {cap:function(P){return'The distance from the origin is the long diagonal of the box: OP = √(x² + y² + z²) = √('+P.x*P.x+' + '+P.y*P.y+' + '+P.z*P.z+') = '+G.N(Math.sqrt(P.x*P.x+P.y*P.y+P.z*P.z))+'. Between two points, use differences: √((x₂−x₁)² + (y₂−y₁)² + (z₂−z₁)²).'},
    draw:function(D,P){var p=pr(P.x,P.y,P.z);D.line(0,0,p[0],p[1],'ok',{w:2.8})}}]};

/* ---- differentiation ---- */
SC.diffgraph={g:'Calculus ideas',t:'Differentiating a power',d:'d/dx of x^n is n x^(n−1): the slope of the curve at a point',i:'xⁿ',
  view:{x0:-0.5,x1:3.2,y0:-1,y1:10},h:280,params:[{k:'n',l:'Power n',min:1,max:4,step:1,v:2},{k:'x',l:'Point x',min:0.5,max:2.5,step:0.5,v:1.5,maxOf:function(P){return Math.max(0.5,Math.min(2.5,Math.floor(Math.pow(9,1/P.n)*2)/2))}}],
  fix:function(P){var m=Math.max(0.5,Math.min(2.5,Math.floor(Math.pow(9,1/P.n)*2)/2));if(P.x>m)P.x=m},
  mini:'To differentiate x to the power n: bring the power down in front, then reduce the power by 1. The result is the slope of the tangent.',
  read:function(P){return'd/dx (x'+pw(P.n)+') = '+P.n+'x'+pw(P.n-1)+'<br>At x = '+P.x+': slope = '+P.n+' × '+P.x+pw(P.n-1)+' = <b>'+G.N(P.n*Math.pow(P.x,P.n-1))+'</b>'},
  steps:[
   {cap:function(P){return'The curve y = x'+pw(P.n)+' and the point P at x = '+P.x+', where y = '+G.N(Math.pow(P.x,P.n))+'.'},
    draw:function(D,P){D.axes(-0.4,3.1,-0.8,9.6,AX);plot(D,function(x){return Math.pow(x,P.n)},0,3.2,{y0:-1,y1:10},'a',{w:2.4});D.dot(P.x,Math.pow(P.x,P.n),'a')}},
   {cap:function(P){var m=P.n*Math.pow(P.x,P.n-1);return'The rule: bring the power down and reduce it by one. d/dx (x'+pw(P.n)+') = '+P.n+'x'+pw(P.n-1)+'. At x = '+P.x+' this is '+P.n+' × '+G.N(Math.pow(P.x,P.n-1))+' = '+G.N(m)+'.'},
    draw:function(D,P){var m=P.n*Math.pow(P.x,P.n-1),y=Math.pow(P.x,P.n),a=-0.4,b=3.1,ya=y+m*(a-P.x),yb=y+m*(b-P.x);
      if(ya<-0.8){a=P.x+(-0.8-y)/m;ya=-0.8}if(yb>9.6){b=P.x+(9.6-y)/m;yb=9.6}D.line(a,ya,b,yb,'ok',{w:2.6});D.txt(2.9,0.3,'slope '+G.N(m),'ok',{a:'end',b:1,s:12})}},
   {cap:function(P){return'The steepness grows with x: slope = '+P.n+'x'+pw(P.n-1)+'. A constant has slope 0, and a multiple just scales: d/dx (c x'+pw(P.n)+') = c × '+P.n+'x'+pw(P.n-1)+'.'},
    draw:function(D,P){D.txt(2.9,9,'dy/dx = '+P.n+'x'+pw(P.n-1),'b',{a:'end',b:1,s:12})}}]};

/* ---- Pascal ---- */
SC.pascal={g:'Counting and algebra',t:'Pascal’s triangle and (a + b)ⁿ',d:'Each number is the sum of the two above; row n gives the coefficients',i:'△',
  view:{x0:-5,x1:5,y0:-0.6,y1:9.6},h:300,params:[{k:'n',l:'Row n',min:0,max:8,step:1,v:5}],
  mini:'Row n lists the coefficients of (a + b)ⁿ, which are nC0, nC1, … nCn. Each number is the sum of the two above it, and each row adds up to 2ⁿ.',
  read:function(P){var r=row(P.n);return'Row '+P.n+': '+r.join(', ')+'<br>(a + b)'+sup(P.n)+' has '+(P.n+1)+' terms · sum = 2'+sup(P.n)+' = <b>'+Math.pow(2,P.n)+'</b>'},
  steps:[
   {cap:'Start with 1 at the top. Every number below is the sum of the two numbers above it, and the edges are always 1.',
    draw:function(D){for(var n=0;n<=8;n++){var r=row(n);r.forEach(function(v,k){D.txt(-n*0.5+k,9-n+0.1,String(v),'m',{s:11,b:1})})}}},
   {cap:function(P){return'Row '+P.n+' (counting the top as row 0) is highlighted: '+row(P.n).join(', ')+'. These are '+row(P.n).map(function(v,k){return P.n+'C'+k}).slice(0,3).join(', ')+'… in order.'},
    draw:function(D,P){var n=P.n;row(n).forEach(function(v,k){D.circ(-n*0.5+k,9-n+0.3,0.42,'ok',{w:2})})}},
   {cap:function(P){return'These are the coefficients of (a + b)'+sup(P.n)+', which has '+(P.n+1)+' terms. Add the row: '+row(P.n).join(' + ')+' = '+Math.pow(2,P.n)+' = 2'+sup(P.n)+'.'},
    draw:function(D,P){D.txt(0,-0.2,'sum = '+Math.pow(2,P.n),'ok',{b:1,s:12})}}]};
function pw(k){return k===1?'':sup(k)}
function row(n){var r=[1];for(var i=1;i<=n;i++)r.push(Math.round(r[i-1]*(n-i+1)/i));return r}

['quadgraph','quadineq','trigplot','radarc','compound','parabola','ellipse','hyperbola','dice','probrule','disp','coord3d','diffgraph','pascal'].forEach(function(id){G.order.push(id)});
G.fig.cquad='quadgraph';G.fig.qsign='quadgraph';G.fig.radian='radarc';G.fig.compound='compound';
})();

