/*THEORY-START*/
/*THEORY: Tutor pack, third document: theory notes for each chapter, with static and animated pictures.
  Claude writes the concepts (big idea, explanation built from definitions, key results, why they are true, a worked example,
  traps tied to the known weak spots, a memory hook) and picks a matching animated picture from the GFX engine, or describes
  a custom diagram that the engine draws. The web version is one self-contained HTML file: the animations play in any browser,
  with Back / Play / Next, and print as the finished picture. Kept on this device (localStorage 'sb_tptheory'). Neutral wording only. */
(function(){
'use strict';
var X=window.TPX;if(!X)return;
var LS='sb_tptheory',ST={busy:null,err:'',pv:false};
function ld(){try{return JSON.parse(localStorage.getItem(LS)||'{}')}catch(e){return{}}}
function get(k){return ld()[k]||null}
function put(k,t){var o=ld();t.ts=Date.now();o[k]=t;try{localStorage.setItem(LS,JSON.stringify(o))}catch(e){throw{full:1}}}
function drop(k){var o=ld();delete o[k];try{localStorage.setItem(LS,JSON.stringify(o))}catch(e){}}
function E(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function H(s){return E(s).replace(/\n/g,'<br>')}
function rr(){try{X.rerender()}catch(e){}}
function msg(t){var m=document.getElementById('thMsg');if(m)m.textContent=t}

/* which ready-made animations suit which chapter (offered first; Claude may pick any maths one) */
var SUG={qe:['quadgraph'],ie:['modulus','quadineq'],ar:['radarc'],tg:['allied','trigplot'],ca:['compound','allied'],pc:['pc'],bt:['binom','pascal'],
  se:['venn'],rf:['funcmap','vlt'],lm:['limit','secant'],dv:['secant','diffgraph'],cx:['ipow','argand'],ss:['ap','gp'],pt:['dist','section'],
  sl:['line','pplines','angle','perp'],ci:['circle','tangent'],pr:['dice','probrule'],cs:['parabola','ellipse','hyperbola'],td:['coord3d'],md:['disp']};
function mathsIds(){var o=[];Object.keys(SUG).forEach(function(k){SUG[k].forEach(function(i){if(o.indexOf(i)<0)o.push(i)})});return o}
function sc(id){return window.GFX&&GFX.scenes&&GFX.scenes[id]||null}
function sceneList(k){var first=(SUG[k]||[]).filter(sc),rest=mathsIds().filter(function(i){return first.indexOf(i)<0&&sc(i)});
  return first.concat(rest).map(function(i){var s=sc(i);return i+': '+s.t+' ('+s.d+')'}).join('\n')}

var DRAW='Return JSON only: {"title":"short title","view":{"x0":number,"x1":number,"y0":number,"y1":number},"eq":true if one unit must look equal on both axes (circles, angles, geometry),"axes":true to draw x and y axes,"steps":[{"cap":"one or two plain sentences saying what this step shows","items":[ ... ]}]}.\n'+
 'Use 2 to 5 steps (1 step for a still picture). Each step ADDS to the earlier ones, so never repeat an item. Item kinds, coordinates in the units of "view": {"t":"l","a":[x,y],"b":[x,y],"c":"a","d":1} line (d:1 dashed); {"t":"ar","a":[x,y],"b":[x,y],"c":"a"} arrow; {"t":"c","p":[x,y],"r":radius,"c":"a","f":1} circle (f:1 lightly filled); {"t":"p","p":[x,y],"l":"label","c":"a","o":1} point (o:1 hollow); {"t":"t","p":[x,y],"s":"text","c":"a","al":"middle"} text; {"t":"pl","pts":[[x,y],...up to 150 points],"c":"a","f":0,"cl":0} curve or polygon (compute the points yourself).\n'+
 'Colours: "a" blue, "b" red, "ok" green, "m" grey, "f" normal. Use colour together with a label, never alone. Labels under 24 characters, maths in Unicode, no markdown, at most 40 items per step. Compute every coordinate carefully so the picture is accurate.';

function weakTxt(k){var L=[];try{L=X.wkAll(k)||[]}catch(e){}return L.length?'\nKnown weak spots of the reader (use them where they really apply): '+L.map(function(w){return w.n}).join('; ')+'.':''}

/* ---------- building ---------- */
async function stPlan(k,t){
  var d=await X.cl(X.TEACH+' You are writing THEORY NOTES for the chapter “'+X.cname(k)+'” of the ISC Class 11 syllabus, for a tutor to teach from and a student to read. '+
   'They should make the reader understand and enjoy the ideas: build each idea from definitions and basic facts, explain why things are true, and show it in pictures.'+weakTxt(k)+
   '\n\nPlan the notes. Choose 5 to 8 concepts in teaching order (foundations first), covering every idea the chapter needs for the exam. For each concept, choose a picture if one helps:\n'+
   '- "fig": the id of a ready-made animated picture from this list when it really shows THIS concept (each id at most once in the plan), else "":\n'+sceneList(k)+
   '\n- "pic": if no ready-made picture fits but a diagram, graph or figure would help, describe it exactly in one or two sentences (what is drawn, with numbers); else "".\n'+
   'Also write "hook": 2 or 3 sentences that open the chapter with a surprising question or a real-life use (economics, music or cricket work well), and "checks": 4 short questions that test understanding of the ideas, not long calculation, each with a short answer.\nAddress the reader as “you”. '+X.MATHNOTE+
   '\nReturn JSON only: {"hook":"...","concepts":[{"t":"concept title, 2 to 7 words","fig":"","pic":""}],"checks":[{"q":"...","a":"..."}]}');
  if(!d||!Array.isArray(d.concepts)||d.concepts.length<3)throw new Error('shape');
  var used={};
  t.hook=String(d.hook||'');
  t.cs=d.concepts.slice(0,8).map(function(c){var f=String(c&&c.fig||'').trim();if(!sc(f)||used[f])f='';if(f)used[f]=1;return{t:String(c&&c.t||'Concept'),fig:f,pic:f?'':String(c&&c.pic||'').slice(0,400)}}).filter(function(c){return c.t});
  t.ck=(d.checks||[]).slice(0,6).map(function(c){return{q:String(c&&c.q||''),a:String(c&&c.a||'')}}).filter(function(c){return c.q});
  t.done=0}
async function stSec(k,t,i){
  var B=[i];if(t.cs[i+1])B.push(i+1);
  var d=await X.cl(X.TEACH+' You are writing THEORY NOTES for the chapter “'+X.cname(k)+'” (ISC Class 11). The full plan of concepts: '+t.cs.map(function(c,j){return(j+1)+'. '+c.t}).join('; ')+'.'+weakTxt(k)+
   '\n\nWrite the notes for these concepts only:\n'+B.map(function(x,j){return'Concept '+(j+1)+': '+t.cs[x].t+(t.cs[x].fig?' (a picture of “'+sc(t.cs[x].fig).t+'” will be shown beside it)':'')}).join('\n')+
   '\n\nFor each give:\n- "idea": the big idea in plain words, 1 or 2 sentences, no symbols if possible.\n- "explain": 120 to 220 words that build the idea from definitions and basic facts, in a warm, lively teaching voice, with an everyday picture or analogy where it helps. Use \\n between paragraphs.\n'+
   '- "results": the key definitions, formulas or results of this concept (1 to 5), each {"f":"the result","note":"what it means or when to use it"}.\n- "why": the reason the main result is true: a short derivation or argument, as 2 to 6 lines.\n'+
   '- "example": one worked example {"q":"the question","steps":["one move per line, with the reason"],"a":"the answer"}, mathematically exact.\n- "traps": 1 to 3 mistakes students often make here; if a known weak spot of the reader applies, say how it shows up in this concept.\n- "remember": one short line to remember the idea by.\n'+
   'Address the reader as “you”. '+X.MATHNOTE+'\nReturn JSON only: {"items":[{"idea":"...","explain":"...","results":[{"f":"...","note":"..."}],"why":["..."],"example":{"q":"...","steps":["..."],"a":"..."},"traps":["..."],"remember":"..."}]}');
  if(!d||!Array.isArray(d.items)||d.items.length<B.length)throw new Error('shape');
  B.forEach(function(x,j){var y=d.items[j];if(!y||!y.explain)throw new Error('shape');var ex=y.example||{};
    t.cs[x].s={i:String(y.idea||''),e:String(y.explain),r:(y.results||[]).slice(0,5).map(function(r){return{f:String(r&&r.f||''),n:String(r&&r.note||'')}}).filter(function(r){return r.f}),
      w:(Array.isArray(y.why)?y.why:[y.why]).filter(Boolean).map(String).slice(0,8),x:ex.q?{q:String(ex.q),s:(ex.steps||[]).map(String).slice(0,10),a:String(ex.a||'')}:null,
      tr:(y.traps||[]).map(String).slice(0,3),m:String(y.remember||'')}})}
async function stPic(k,t,i){
  var c=t.cs[i],d=await X.cl('You are the diagram maker for theory notes in a study app for a senior-school student. Chapter: '+X.cname(k)+'. Concept: '+c.t+'.\nDraw a clear, accurate, simple diagram, built step by step, of:\n'+c.pic+'\n\n'+DRAW);
  var ok=window.GFX&&GFX.cleanSpec&&GFX.cleanSpec(d);c.sp=ok?d:null;c.pd=1}
async function build(k){
  var t=get(k)||{id:k,cs:null};
  try{
    if(!t.cs){msg('Planning the concepts and pictures…');await stPlan(k,t);put(k,t)}
    for(var i=0;i<t.cs.length;i+=2){if(t.cs[i].s&&(!t.cs[i+1]||t.cs[i+1].s))continue;msg('Writing concepts '+(i+1)+(t.cs[i+1]?' and '+(i+2):'')+' of '+t.cs.length+'…');await stSec(k,t,i);put(k,t)}
    var P=t.cs.map(function(c,j){return j}).filter(function(j){return t.cs[j].pic&&!t.cs[j].pd}).slice(0,5);
    for(var n=0;n<P.length;n++){msg('Drawing picture '+(n+1)+' of '+P.length+'…');try{await stPic(k,t,P[n])}catch(e){if(e&&(e.nos||e.code))throw e;t.cs[P[n]].pd=1}put(k,t)}
    t.cs.forEach(function(c){if(c.pic)c.pd=1});t.done=1;put(k,t);return true
  }catch(e){ST.err=X.errText(e);return false}}
window.tpThBuild=async function(k){if(ST.busy)return;ST.busy=k;ST.err='';rr();await build(k);ST.busy=null;rr()};
window.tpThRebuild=function(k){if(ST.busy)return;drop(k);ST.pv=false;ST.err='';rr()};

/* ---------- pictures: every step of a GFX scene is drawn once and kept as a frame ---------- */
var FC={};
function frames(s,key){if(key&&FC[key])return FC[key];if(!s||!window.GFX)return null;
  var host=document.createElement('div');host.style.cssText='position:absolute;left:-9999px;top:0;width:360px';document.body.appendChild(host);var F=[];
  try{var p=GFX.player(host,s,{auto:false});for(var k=0;k<s.steps.length;k++){p.go(k,false);var g=host.querySelector('svg');F.push({svg:g?g.outerHTML.replace(/ class="gfx-new"/g,''):'',cap:(host.querySelector('.gfxcap')||{}).textContent||''})}try{p.stop()}catch(e){}}
  catch(e){F=[]}host.remove();F=F.filter(function(f){return f.svg});if(!F.length)return null;var o={t:s.t,mini:s.mini||'',f:F};if(key)FC[key]=o;return o}
function figOf(c){if(c.fig)return frames(sc(c.fig),c.fig);if(c.sp){var s=GFX.cleanSpec(c.sp);return s?frames(s,null):null}return null}
function figHtml(o,n){if(!o)return'';var one=o.f.length===1;
  return'<figure class="fig'+(one?' still':'')+'" data-n="'+o.f.length+'"><div class="fh"><b>Figure '+n+'</b> · '+E(o.t)+(one?'':' <span class="tag">animated</span>')+'</div><div class="frames">'+
    o.f.map(function(f,i){return'<div class="fr'+(i===(one?0:0)?' on':'')+(i===o.f.length-1?' last':'')+'" data-cap="'+E(f.cap)+'">'+f.svg+'</div>'}).join('')+'</div>'+
    '<figcaption class="cap">'+E(o.f[0].cap)+'</figcaption>'+(one?'':'<div class="ctl"><button type="button" data-a="b">◀ Back</button><button type="button" data-a="p" class="pp">▶ Play</button><button type="button" data-a="n">Next ▶</button><span class="st">Step 1 of '+o.f.length+'</span></div>')+
    (o.mini?'<p class="mini">'+E(o.mini)+'</p>':'')+'</figure>'}

/* ---------- the document ---------- */
var CSS=':root{--bg:#fff;--fg:#1b1d24;--card:#fff;--muted:#646a7a;--line:#dcdfe8;--accent:#3b5bdb;--accent-soft:#e7ecff;--ok:#2b8a3e;--bad:#c92a2a}'+
 '*{box-sizing:border-box}body{font:16px/1.6 Georgia,"Times New Roman",serif;color:var(--fg);background:#f4f5f8;margin:0}main{max-width:820px;margin:0 auto;padding:18px 16px 40px}'+
 'h1{font:700 1.7rem/1.2 system-ui,sans-serif;margin:0 0 4px}h2{font:700 1.25rem/1.3 system-ui,sans-serif;margin:0 0 8px;color:var(--accent)}h3{font:700 .8rem/1.3 system-ui,sans-serif;text-transform:uppercase;letter-spacing:.05em;color:#444;margin:16px 0 6px}'+
 '.meta{font:.9rem system-ui,sans-serif;color:var(--muted);margin:0 0 14px}.hook{font-size:1.08rem;font-style:italic;border-left:4px solid var(--accent);padding:4px 0 4px 14px;margin:0 0 16px}'+
 '.toc{background:#fff;border:1px solid var(--line);border-radius:12px;padding:10px 16px;margin:0 0 18px;font-family:system-ui,sans-serif;font-size:.95rem}.toc ol{margin:6px 0 0;padding-left:22px}.toc a{color:var(--accent);text-decoration:none}'+
 'section.cp{background:#fff;border:1px solid var(--line);border-radius:14px;padding:16px 18px;margin:0 0 18px}.num{display:inline-block;min-width:1.8em;height:1.8em;line-height:1.8em;text-align:center;border-radius:50%;background:var(--accent);color:#fff;font-size:.9rem;margin-right:6px}'+
 '.idea{background:var(--accent-soft);border-radius:10px;padding:10px 14px;font:600 1rem/1.5 system-ui,sans-serif;margin:0 0 12px}.idea small{display:block;font-size:.72rem;letter-spacing:.06em;text-transform:uppercase;color:var(--accent);margin-bottom:2px}'+
 'table{border-collapse:collapse;width:100%;font-size:.95rem}td,th{border:1px solid var(--line);padding:6px 9px;text-align:left;vertical-align:top}th{background:#f1f3f8;font:600 .85rem system-ui,sans-serif}td.f{font-weight:700;white-space:pre-wrap}'+
 '.why{margin:0;padding-left:20px}.ex{border:1px solid var(--line);border-radius:10px;padding:10px 14px;background:#fafbfd}.ex ol{margin:6px 0;padding-left:22px}.ans{font-weight:700;color:var(--ok)}'+
 '.trap{border-left:4px solid var(--bad);background:#fdf3f3;padding:8px 12px;border-radius:0 8px 8px 0;margin:10px 0}.trap ul{margin:4px 0 0;padding-left:20px}.rem{font:600 .98rem system-ui,sans-serif;margin:12px 0 0}.rem::before{content:"💡 "}'+
 '.fig{margin:14px 0;border:1px solid var(--line);border-radius:12px;padding:10px 12px;background:#fff;break-inside:avoid}.fh{font:.85rem system-ui,sans-serif;color:var(--muted);margin-bottom:6px}.tag{background:var(--accent-soft);color:var(--accent);border-radius:20px;padding:1px 8px;font-size:.75rem;font-weight:600}'+
 '.frames{max-width:460px;margin:0 auto}.fr{display:none}.fr.on{display:block;animation:fi .6s ease}@keyframes fi{from{opacity:.25}to{opacity:1}}.fr svg{display:block;width:100%;height:auto;border-radius:10px}'+
 '.cap{font:.95rem/1.45 system-ui,sans-serif;min-height:2.9em;margin:8px 2px}.mini{font:.88rem/1.45 system-ui,sans-serif;color:var(--muted);margin:4px 2px 0}'+
 '.ctl{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-family:system-ui,sans-serif}.ctl button{min-height:40px;padding:0 14px;border:1px solid var(--accent);background:#fff;color:var(--accent);border-radius:10px;font:600 .9rem system-ui,sans-serif;cursor:pointer}.ctl button.pp{background:var(--accent);color:#fff}.ctl .st{font-size:.8rem;color:var(--muted);margin-left:auto}'+
 '.chk details{border:1px solid var(--line);border-radius:10px;padding:8px 12px;margin:8px 0;background:#fff}.chk summary{cursor:pointer;font-weight:600}.foot{font:.8rem system-ui,sans-serif;color:var(--muted);margin-top:20px}'+
 '@media print{body{background:#fff;font-size:11pt}main{padding:0}section.cp{border:0;padding:0;margin:0 0 14px;break-inside:auto}.ctl,.toc{display:none}.fr{display:none!important}.fr.last{display:block!important;animation:none}.cap{display:none}.chk details{border:0;padding:0}.chk details>*{display:block}}'+
 '@media (prefers-reduced-motion:reduce){.fr.on{animation:none}}';
var JS='(function(){var R=false;try{R=matchMedia("(prefers-reduced-motion: reduce)").matches}catch(e){}'+
 'document.querySelectorAll(".fig[data-n]").forEach(function(f){var fr=f.querySelectorAll(".fr"),n=fr.length,i=0,t=null,cap=f.querySelector(".cap"),st=f.querySelector(".st"),pp=f.querySelector(".pp");if(n<2)return;'+
 'function show(k){i=Math.max(0,Math.min(n-1,k));fr.forEach(function(x,j){x.classList.toggle("on",j===i)});cap.textContent=fr[i].getAttribute("data-cap");if(st)st.textContent="Step "+(i+1)+" of "+n;if(pp)pp.textContent=t?"⏸ Pause":(i>=n-1?"↺ Replay":"▶ Play")}'+
 'function stop(){if(t){clearInterval(t);t=null}}function play(){if(i>=n-1)show(0);stop();t=setInterval(function(){if(i<n-1)show(i+1);else{stop();show(i)}},3800);show(i)}'+
 'f.querySelector(".ctl").addEventListener("click",function(e){var a=e.target.getAttribute("data-a");if(!a)return;if(a==="p"){t?(stop(),show(i)):play()}else{stop();show(i+(a==="n"?1:-1))}});'+
 'show(0);if(!R&&"IntersectionObserver" in window){var o=new IntersectionObserver(function(es){es.forEach(function(en){if(en.isIntersecting){o.disconnect();play()}})},{threshold:.5});o.observe(f)}})})();';
function docHtml(k){var t=get(k),n=X.cname(k),fn=0,b='<main><h1>Theory notes · '+E(n)+'</h1><div class="meta">'+t.cs.length+' concepts · pictures and animations · Study Buddy tutor pack</div>';
  if(t.hook)b+='<p class="hook">'+H(t.hook)+'</p>';
  b+='<nav class="toc"><b>In these notes</b><ol>'+t.cs.map(function(c,i){return'<li><a href="#c'+(i+1)+'">'+E(c.t)+'</a></li>'}).join('')+(t.ck.length?'<li><a href="#chk">Check your understanding</a></li>':'')+'<li><a href="#rec">Recap of results</a></li></ol></nav>';
  t.cs.forEach(function(c,i){var s=c.s;if(!s)return;b+='<section class="cp" id="c'+(i+1)+'"><h2><span class="num">'+(i+1)+'</span>'+E(c.t)+'</h2>';
    if(s.i)b+='<div class="idea"><small>The big idea</small>'+H(s.i)+'</div>';
    b+=s.e.split(/\n+/).map(function(p){return'<p>'+E(p)+'</p>'}).join('');
    var f=figOf(c);if(f)b+=figHtml(f,++fn);
    if(s.r.length)b+='<h3>Key results</h3><table>'+s.r.map(function(r){return'<tr><td class="f">'+E(r.f)+'</td><td>'+H(r.n)+'</td></tr>'}).join('')+'</table>';
    if(s.w.length)b+='<h3>Why it is true</h3><ol class="why">'+s.w.map(function(w){return'<li>'+H(w)+'</li>'}).join('')+'</ol>';
    if(s.x)b+='<h3>Worked example</h3><div class="ex"><b>'+H(s.x.q)+'</b><ol>'+s.x.s.map(function(x){return'<li>'+H(x)+'</li>'}).join('')+'</ol><div class="ans">Answer: '+H(s.x.a)+'</div></div>';
    if(s.tr.length)b+='<div class="trap"><b>Watch out</b><ul>'+s.tr.map(function(x){return'<li>'+H(x)+'</li>'}).join('')+'</ul></div>';
    if(s.m)b+='<p class="rem">'+H(s.m)+'</p>';b+='</section>'});
  if(t.ck.length)b+='<section class="cp chk" id="chk"><h2>Check your understanding</h2><p class="meta">Try each one first, then open it to see the answer.</p>'+t.ck.map(function(c,i){return'<details><summary>'+(i+1)+'. '+H(c.q)+'</summary><p>'+H(c.a)+'</p></details>'}).join('')+'</section>';
  b+='<section class="cp" id="rec"><h2>Recap of results</h2><table><tr><th>Concept</th><th>Result</th></tr>'+t.cs.map(function(c){return c.s?c.s.r.map(function(r,j){return'<tr><td>'+(j?'':E(c.t))+'</td><td class="f">'+E(r.f)+'</td></tr>'}).join(''):''}).join('')+'</table></section>';
  b+='<p class="foot">Written with Claude for the Study Buddy tutor pack. Please read it before teaching from it. Animations play on screen; printing shows each finished picture.</p></main>';
  return'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Theory notes · '+E(n)+'</title><style>'+CSS+'</style></head><body>'+b+'<script>'+JS+'<\/script></body></html>'}
function fname(k){return'StudyBuddy-'+X.cname(k).replace(/[^A-Za-z0-9]+/g,'-').replace(/^-|-$/g,'')+'-theory-notes'}
window.tpThDown=function(k){var t=get(k);if(!t||!t.done)return;X.saveBlob(new Blob([docHtml(k)],{type:'text/html'}),fname(k)+'.html','Web version saved. It opens in any browser, with the animations, and can be sent as a file.')};
window.tpThPrint=function(k){var t=get(k);if(!t||!t.done)return;var f=document.createElement('iframe');f.style.cssText='position:fixed;right:0;bottom:0;width:0;height:0;border:0';document.body.appendChild(f);
  f.onload=function(){try{f.contentWindow.focus();f.contentWindow.print()}catch(e){try{showToast('Printing is blocked here. Save the web version and print it from the browser.')}catch(x){}}setTimeout(function(){try{f.remove()}catch(e){}},120000)};f.srcdoc=docHtml(k)};
window.tpThPreview=function(){ST.pv=!ST.pv;rr()};

/* ---------- the card on the chapter page ---------- */
window.tpThCard=function(k){var t=get(k),h='<div class="card"><b>Theory notes</b> <span class="pill st">with pictures</span>';
  if(ST.busy===k)return h+'<p class="sub" id="thMsg" aria-live="polite" style="margin:6px 0 0">Starting…</p><p class="sub" style="margin:8px 0 0">This takes a few minutes. Keep this page open; finished parts are saved as it goes.</p></div>';
  var er=ST.err&&!ST.busy?'<div class="fb bad" style="margin:6px 0">'+E(ST.err)+'</div>':'';
  if(t&&t.done){var nf=t.cs.filter(function(c){return c.fig||c.sp}).length;
    h+='<p class="sub" style="margin:4px 0 6px">'+t.cs.length+' concepts, each with the big idea, an explanation built from the basics, key results, why they are true, a worked example and the traps to watch'+(nf?', and '+nf+' picture'+(nf>1?'s':'')+' (animated ones play step by step)':'')+'. Ends with check questions and a recap of results.</p>'+er+
      '<button class="btn" onclick="tpThDown(\''+k+'\')">Save the web version to send</button><button class="btn alt" onclick="tpThPrint(\''+k+'\')">Print</button><button class="link" onclick="tpThPreview()" style="margin-top:6px">'+(ST.pv?'Hide preview':'Preview')+'</button>'+
      (ST.pv?'<iframe id="thPv" title="Theory notes preview" style="width:100%;height:75vh;border:1px solid var(--line);border-radius:10px;margin-top:8px;background:#fff"></iframe>':'')+
      '<button class="link" onclick="tpThRebuild(\''+k+'\')" style="margin-top:8px;display:block">Write fresh notes</button></div>';
    if(ST.pv)setTimeout(function(){var f=document.getElementById('thPv');if(f&&!f.srcdoc)f.srcdoc=docHtml(k)},0);return h}
  if(t&&t.cs)return h+'<p class="sub" style="margin:4px 0 0">'+t.cs.length+' concepts planned, '+t.cs.filter(function(c){return c.s}).length+' written so far.</p>'+er+'<button class="btn" onclick="tpThBuild(\''+k+'\')">Continue writing</button></div>';
  return h+'<p class="sub" style="margin:4px 0 6px">The chapter’s concepts explained from the basics, with static and animated pictures, worked examples, traps tied to the known weak spots, check questions and a recap. Saved as a web page that plays the animations in any browser.</p>'+er+'<button class="btn" onclick="tpThBuild(\''+k+'\')">Write the theory notes</button></div>'};
})();
